from itertools import combinations
from math import exp
observed = ['H','V','R','Y']
graphs = {
    'simulation': [('U','H'),('U','V'),('H','R'),('C','R'),('V','Y'),('C','Y')],
    'compatible_H_causal': [('H','V'),('H','R'),('C','R'),('V','Y'),('C','Y')]
}
def d_separated(edges, a, b, conditioned):
    parents={}
    for p,c in edges:
        parents.setdefault(c,set()).add(p)
        parents.setdefault(p,set())
    ancestors=set(conditioned)|{a,b}
    pending=list(ancestors)
    while pending:
        for p in parents[pending.pop()]:
            if p not in ancestors:
                ancestors.add(p)
                pending.append(p)
    adjacent={v:set() for v in ancestors}
    for child in ancestors:
        ps=parents[child]&ancestors
        for p in ps:
            adjacent[p].add(child)
            adjacent[child].add(p)
        for p,q in combinations(ps,2):
            adjacent[p].add(q)
            adjacent[q].add(p)
    reached={a}
    pending=[a]
    while pending:
        for v in adjacent[pending.pop()]-set(conditioned)-reached:
            reached.add(v)
            pending.append(v)
    return b not in reached
patterns={}
for label,edges in graphs.items():
    cis=[]
    for a,b in combinations(observed,2):
        rest=[v for v in observed if v not in [a,b]]
        for k in range(len(rest)+1):
            for cond in combinations(rest,k):
                if d_separated(edges,a,b,cond):
                    cis.append((a,b,cond))
    patterns[label]=cis
    print(label, 'observed conditional independences:',cis)
print('Identical observed CI patterns:',len(set(map(str,patterns.values())))==1)
expit=lambda t:1/(1+exp(-t))
mean_v0=(expit(-0.5)+expit(1.25))/2
mean_v1=(expit(2)+expit(3.75))/2
print('Under the stated simulation, E[Y|H=1]=',2*mean_v0/3+mean_v1/3)
print('Under the stated simulation, E[Y|H=0]=',mean_v0/3+2*mean_v1/3)
print('Reported bird split sum:',2849+520+529,'versus total 3538')
print('Correct predictions implied by stated X-ray accuracy and test size:',50*0.7455)
PY"
